            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">PROCESSUAL ARCHAEOLOGY</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The New Archaeology, 1960s</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">FOUNDER: LEWIS BINFORD</text>\n                    <text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Archaeology should be a hard science</text>\n                    <rect x=\"100\" y=\"350\" width=\"430\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"315\" y=\"400\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">METHOD</text>\n                    <text x=\"315\" y=\"445\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Hypothesis testing</text>\n                    <text x=\"315\" y=\"485\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Statistics</text>\n                    <text x=\"315\" y=\"525\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Systems theory</text>\n                    <rect x=\"570\" y=\"350\" width=\"430\" height=\"200\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"785\" y=\"400\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">FOCUS</text>\n                    <text x=\"785\" y=\"445\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Ecology + environment</text>\n                    <text x=\"785\" y=\"485\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Economy + subsistence</text>\n                    <text x=\"785\" y=\"525\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Cultural processes</text>\n                    <rect x=\"100\" y=\"580\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"630\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">GOAL</text>\n                    <text x=\"550\" y=\"680\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">General laws of human behavior</text>\n                    <text x=\"550\" y=\"715\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Why did cultures change?</text>\n                    <rect x=\"100\" y=\"770\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"820\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">CRITIQUE</text>\n                    <text x=\"550\" y=\"860\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Cold, dehumanizing, eco-deterministic</text>\n                </svg>",
