            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Two paradigms, one site</text>\n                    <rect x=\"60\" y=\"200\" width=\"490\" height=\"380\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"305\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">PROCESSUAL ASKS</text>\n                    <text x=\"305\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">How did the system</text>\n                    <text x=\"305\" y=\"365\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">function?</text>\n                    <text x=\"305\" y=\"430\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Economy + ecology</text>\n                    <rect x=\"580\" y=\"200\" width=\"490\" height=\"380\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"825\" y=\"260\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">POST-PROCESSUAL ASKS</text>\n                    <text x=\"825\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">What did the symbols</text>\n                    <text x=\"825\" y=\"365\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">mean?</text>\n                    <text x=\"825\" y=\"430\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Identity + ideology</text>\n                </svg>",
            "caption": "Where the paradigms diverge"
