            "type": "diagram",
            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">VESUVIUS CHALLENGE</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Reading carbonized books</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"255\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">VILLA OF THE PAPYRI</text>\n                    <text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">~1,800 carbonized scrolls</text>\n                    <text x=\"550\" y=\"340\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Only intact ancient library</text>\n                    <rect x=\"100\" y=\"380\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"435\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">VIRTUAL UNROLLING</text>\n                    <text x=\"550\" y=\"485\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Brent Seales: X-ray micro-CT</text>\n                    <text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">AI finds invisible ink traces</text>\n                    <rect x=\"100\" y=\"560\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"615\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">2023: FIRST WORD READ</text>\n                    <text x=\"550\" y=\"665\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">πορφύρας ('purple')</text>\n                    <text x=\"550\" y=\"700\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Luke Farritor, age 21</text>\n                    <rect x=\"100\" y=\"740\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"795\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">2024: 2,000+ CHARACTERS</text>\n                    <text x=\"550\" y=\"845\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">First paragraphs decoded</text>\n                    <text x=\"550\" y=\"880\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Lost classics may emerge</text>\n                    <rect x=\"100\" y=\"920\" width=\"900\" height=\"60\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"960\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">Computational archaeology</text>\n                </svg>",
            "caption": "Reading the unreadable"
