            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">FINAL CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">PACUNAM rewrites Maya</text>\n                    <rect x=\"60\" y=\"200\" width=\"490\" height=\"280\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"305\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">OLD ESTIMATE</text>\n                    <text x=\"305\" y=\"335\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"36\">~5M</text>\n                    <text x=\"305\" y=\"400\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Pre-LiDAR consensus</text>\n                    <rect x=\"580\" y=\"200\" width=\"490\" height=\"280\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"825\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">NEW ESTIMATE</text>\n                    <text x=\"825\" y=\"335\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"36\">10-15M</text>\n                    <text x=\"825\" y=\"400\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Post-PACUNAM</text>\n                    <rect x=\"150\" y=\"560\" width=\"800\" height=\"280\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"630\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"26\">60,000+ NEW STRUCTURES</text>\n                    <text x=\"550\" y=\"700\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Houses, terraces, roads, walls</text>\n                    <text x=\"550\" y=\"760\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Hyperdense civilization</text>\n                    <text x=\"550\" y=\"810\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Like medieval Europe</text>\n                </svg>",
            "caption": "Maya scale revolution"
