            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">FINAL CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The 1899 origin</text>\n                    <rect x=\"150\" y=\"220\" width=\"800\" height=\"240\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">WANG YIRONG, 1899</text>\n                    <text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Reads inscription on</text>\n                    <text x=\"550\" y=\"395\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">'dragon bone' prescription</text>\n                    <rect x=\"150\" y=\"500\" width=\"800\" height=\"240\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"570\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">SHANG ORACLE BONES</text>\n                    <text x=\"550\" y=\"630\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">150,000+ fragments found</text>\n                    <text x=\"550\" y=\"675\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">at Anyang excavations</text>\n                    <rect x=\"150\" y=\"780\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"840\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">A scholar reading his medicine</text>\n                    <text x=\"550\" y=\"890\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">launched a whole science</text>\n                    <text x=\"550\" y=\"935\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Curiosity meets recognition</text>\n                </svg>",
