            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">SCIENCE VS TREASURE</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The underwater fight</text>\n                    <rect x=\"60\" y=\"200\" width=\"490\" height=\"380\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"305\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">TREASURE HUNTING</text>\n                    <text x=\"305\" y=\"320\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Sells artifacts</text>\n                    <text x=\"305\" y=\"370\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Loses context</text>\n                    <text x=\"305\" y=\"420\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Private ownership</text>\n                    <text x=\"305\" y=\"470\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Atocha, Central America</text>\n                    <text x=\"305\" y=\"540\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Destroys information</text>\n                    <rect x=\"580\" y=\"200\" width=\"490\" height=\"380\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"825\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">UNDERWATER ARCH</text>\n                    <text x=\"825\" y=\"320\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Records everything</text>\n                    <text x=\"825\" y=\"370\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Preserves context</text>\n                    <text x=\"825\" y=\"420\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Public collections</text>\n                    <text x=\"825\" y=\"470\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Mary Rose, Uluburun</text>\n                    <text x=\"825\" y=\"540\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Knowledge preserved</text>\n                    <rect x=\"100\" y=\"620\" width=\"900\" height=\"160\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"675\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">UNESCO 2001 CONVENTION</text>\n                    <text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Wrecks 100+ yrs = cultural heritage</text>\n                    <text x=\"550\" y=\"760\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">70+ countries ratified</text>\n                    <rect x=\"100\" y=\"800\" width=\"900\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"855\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">A coin without context</text>\n                    <text x=\"550\" y=\"905\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">tells you nothing.</text>\n                    <text x=\"550\" y=\"950\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Provenance is the science.</text>\n                </svg>",
