            "type": "diagram",
            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The cutoff date</text>\n                    <rect x=\"150\" y=\"220\" width=\"800\" height=\"280\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"30\">1970</text>\n                    <text x=\"550\" y=\"360\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">UNESCO Convention</text>\n                    <text x=\"550\" y=\"410\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">on Illicit Cultural Property</text>\n                    <text x=\"550\" y=\"460\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">142+ countries ratified</text>\n                    <rect x=\"150\" y=\"560\" width=\"800\" height=\"280\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"625\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Cutoff date for ethical acquisition</text>\n                    <text x=\"550\" y=\"680\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Pre-1970 = presumed legal</text>\n                    <text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Post-1970 = needs proof</text>\n                    <text x=\"550\" y=\"785\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">AAMD + ICOM + AAM standard</text>\n                </svg>",
            "caption": "The 1970 standard"
