            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">DEEP LEARNING + SCRIPTS</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Reading what was unreadable</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">1952 - VENTRIS + LINEAR B</text>\n                    <text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Pattern analysis template</text>\n                    <rect x=\"100\" y=\"340\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"390\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">INDUS SCRIPT</text>\n                    <text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Rao, Mukhopadhyay - Markov + ML</text>\n                    <rect x=\"100\" y=\"480\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"530\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">VESUVIUS CHALLENGE 2023-24</text>\n                    <text x=\"550\" y=\"570\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">CNN reads charred Herculaneum scrolls</text>\n                    <rect x=\"100\" y=\"620\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"670\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">'PORPHYRAS' - OCT 2023</text>\n                    <text x=\"550\" y=\"710\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">First word read by Luke Farritor</text>\n                    <rect x=\"100\" y=\"760\" width=\"900\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"810\" text-anchor=\"middle\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">DSS + FRAGMENTARIUM</text>\n                    <text x=\"550\" y=\"850\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">ML rejoins tablets + ID scribes</text>\n                    <rect x=\"100\" y=\"900\" width=\"900\" height=\"80\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"950\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">A golden age of decipherment</text>\n                </svg>",
            "caption": "Script frontiers"
