            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">UNSOLVED MYSTERIES</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The great open problems</text>\n                    <rect x=\"80\" y=\"180\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"225\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">1.</text>\n                    <text x=\"180\" y=\"225\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Indus script decipherment</text>\n                    <rect x=\"80\" y=\"265\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"310\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">2.</text>\n                    <text x=\"180\" y=\"310\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Bronze Age collapse (1200 BCE)</text>\n                    <rect x=\"80\" y=\"350\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"395\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">3.</text>\n                    <text x=\"180\" y=\"395\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Sea Peoples identity</text>\n                    <rect x=\"80\" y=\"435\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"480\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"20\">4.</text>\n                    <text x=\"180\" y=\"480\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Classic Maya collapse mechanics</text>\n                    <rect x=\"80\" y=\"520\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"565\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"20\">5.</text>\n                    <text x=\"180\" y=\"565\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Peopling of the Americas</text>\n                    <rect x=\"80\" y=\"605\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(20,184,166,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"650\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">6.</text>\n                    <text x=\"180\" y=\"650\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Gobekli Tepe function</text>\n                    <rect x=\"80\" y=\"690\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"735\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">7.</text>\n                    <text x=\"180\" y=\"735\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Trans-Pacific contact</text>\n                    <rect x=\"80\" y=\"775\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"820\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">8.</text>\n                    <text x=\"180\" y=\"820\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Lost tombs: Alexander, Cleopatra</text>\n                    <rect x=\"80\" y=\"860\" width=\"940\" height=\"70\" rx=\"15\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"905\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">9.</text>\n                    <text x=\"180\" y=\"905\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">Neanderthal extinction</text>\n                    <rect x=\"80\" y=\"900\" width=\"940\" height=\"80\" rx=\"15\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"950\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"20\">10. How many sites still out there?</text>\n                </svg>",
